import {serviceComponents,type ServiceComponent,type ServiceTotals} from '@/lib/service-days';
export type ServiceAmounts=Record<ServiceComponent,number>;
export const taxBuckets=[['legacy','Combined tax'],['city','City tax'],['state','State tax'],['lodging','Lodging tax'],['unallocated','Uncategorized tax']] as const;
export type TaxBucket=typeof taxBuckets[number][0];
export type TaxAmounts=Record<TaxBucket,number>;
export const feeBuckets=[["legacy","Combined property fee"],["resort","Resort fee"],["technology","Technology fee"],["cleaning","Cleaning fee"],["unallocated","Uncategorized property fee"]] as const;
export type FeeAmounts=Record<typeof feeBuckets[number][0],number>;
export type ForwardPreview={target_fee_buckets?:FeeAmounts|null;allocated_fee_buckets?:FeeAmounts|null;suggested_fee_delta?:FeeAmounts|null;target_tax_buckets?:TaxAmounts|null;suggested_tax_delta?:TaxAmounts|null;reservation_id:string;guest_name:string|null;status:string;arrival:string;departure:string;original_service_start:string|null;original_service_end:string|null;allocated_nights:number;source_version:number;book_version:number|null;service_date:string|null;time_zone:string|null;pricing_hash:string;preview_hash:string;financial_basis:string;current_total_minor:number|null;component_totals_fixed:boolean;target_components:ServiceAmounts;original_components:ServiceAmounts;allocated_components:ServiceAmounts;allocated_tax_buckets:TaxAmounts;required_total_delta:number|null;suggested_delta:ServiceAmounts|null;reconciliation_pending:boolean;eligible:boolean;blockers:string[];prior_adjustments:{adjustment_id:string;service_date:string;delta:ServiceAmounts;tax_buckets:TaxAmounts;fee_buckets?:FeeAmounts|null;reason:string;created_at:string;posted:boolean}[];generated_at:string};
export type PendingForward={adjustment_id:string;reservation_id:string;service_date:string;source_version:number;pricing_hash:string;delta:ServiceAmounts;tax_buckets:TaxAmounts;total_minor:number;reason:string;approved_by:string;approved_at:string;original_service_start:string;original_service_end:string};
export type ForwardEntry=ServiceAmounts&{service_date:string;adjustment_id:string;reservation_id:string;total_minor:number;tax_buckets:TaxAmounts;details:{reason:string;approved_by:string;approved_at:string;source_version:number;pricing_hash:string;original_service_start:string;original_service_end:string;guest_name:string|null;financial_basis:string}};
export type ForwardReceipt={fee_buckets?:FeeAmounts|null;adjustment_id:string;reservation_id:string;service_date:string;delta:ServiceAmounts;tax_buckets:TaxAmounts;total_minor:number;allocated_components_after:ServiceAmounts;allocated_tax_buckets_after:TaxAmounts;pricing_hash:string;book_version:number;posted:false;folio_changed:false;reason:string;replayed:boolean};
export type CorrectionTotals=ServiceTotals&{correction_rows:number};
export function signedCents(value:FormDataEntryValue|null){const text=typeof value==='string'?value:'';if(!/^[+-]?(0|[1-9]\d{0,9})(\.\d{1,2})?$/.test(text))throw Error('Enter a signed USD amount with up to two decimal places.');const negative=text.startsWith('-'),[whole,fraction='']=text.replace(/^[+-]/,'').split('.');const amount=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(amount>999999999999)throw Error('Correction amount exceeds the supported range.');return negative?-amount:amount}
export function validateForward(data:ForwardPreview,delta:ServiceAmounts,taxes:TaxAmounts){
 const sum=serviceComponents.reduce((n,[key])=>n+delta[key],0);if(sum!==data.required_total_delta)throw Error('The correction must reconcile the exact difference between current charges and all previous allocations.');
 for(const [key,label] of serviceComponents){const after=data.allocated_components[key]+delta[key];if(!Number.isSafeInteger(delta[key])||Math.abs(delta[key])>999999999999)throw Error(label+' correction is outside the supported range.');if(after<0)throw Error(label+' cannot become negative.');if(after>999999999999)throw Error(label+' resulting allocation exceeds the supported range.');if(data.component_totals_fixed&&after!==data.target_components[key])throw Error(label+' must reconcile to its required component total.');}
 if(taxBuckets.reduce((n,[key])=>n+taxes[key],0)!==delta.taxes_minor)throw Error('The five tax categories must add up to the tax correction.');
 for(const [key,label] of taxBuckets){const after=data.allocated_tax_buckets[key]+taxes[key];if(!Number.isSafeInteger(taxes[key])||Math.abs(taxes[key])>999999999999)throw Error(label+' correction is outside the supported range.');if(after<0)throw Error(label+' cannot become negative.');if(after>999999999999)throw Error(label+' resulting allocation exceeds the supported range.');if(data.target_tax_buckets&&after!==data.target_tax_buckets[key])throw Error(label+' must reconcile to its recorded tax target.');}
}
